-- 49_backfill_unresolvable_pq_object_archive.sql
--
-- Repairs a data-loss mistake made by the first revision of migration 47.
--
-- That revision DELETED the 1,842 unresolvable Type-2 public-quest spawn rows outright, on the
-- stated grounds that they were "junk" duplicated on top of the real spawns. Re-checking the
-- claim against the untouched base dump (`Database/war_world.7z`, table `pquest_spawns`,
-- 29,437 rows) showed the duplication claim was false: measured against the same objective's
-- surviving Type-1 rows, only 34 of the 1,842 sit within 50 units and 1,640 are more than 300
-- units away. Their positions are their own and are potentially identifiable against the packet
-- captures, exactly as migrations 38, 41, 43, 46 and 48 identified 39 other prototypes from
-- position alone. Destroying them was the wrong remedy.
--
-- Migration 47 has been rewritten to move such rows into `pquest_spawns_unresolved` instead of
-- deleting them. This script restores the archive contents on a database where the original
-- deleting revision of 47 had already run, so that database ends up in the same state a fresh
-- run of the rewritten 47 produces.
--
-- The rows below are verbatim from the base dump. They are NOT put back into `pquest_spawns`:
-- they still cannot resolve (no `gameobject_protos` row) and sit on kill objectives that cannot
-- be satisfied by a game object, and every one of those objectives retains its full Type-1
-- creature set. The archive is the record, not a live placement.
--
-- The base dump's `pquest_spawns` predates the `Ward` and `CaptureDuration` columns the ORM has
-- since added, so those two default to 0 here -- the same value they carry on every other
-- surviving Type-2 row.
--
-- Idempotent: INSERT IGNORE on the primary key; a second run inserts nothing, and on a database
-- where the rewritten 47 already archived these rows this script is a no-op.
--
-- USE `war_world`;

USE `war_world`;

CREATE TABLE IF NOT EXISTS `pquest_spawns_unresolved` LIKE `pquest_spawns`;

INSERT IGNORE INTO `pquest_spawns_unresolved`
    (`pquest_spawns_ID`, `Entry`, `ZoneId`, `WorldX`, `WorldY`, `WorldZ`, `WorldO`, `Objective`,
     `Type`, `Emote`, `Level`, `SoundId`, `VfxState`, `AllowVfxUpdate`, `Unks`, `Unk3`)
