-- Verification.
--   archived_rows            -- 1842
--   leaked_back_into_live    -- must be 0: nothing is re-added to pquest_spawns
--   kill_objectives_empty    -- must be 0: every affected objective still has its spawns
SELECT
    (SELECT COUNT(*) FROM pquest_spawns_unresolved)                                AS archived_rows,
    (SELECT COUNT(*) FROM pquest_spawns s
       JOIN pquest_objectives o ON o.Guid = s.Objective
       LEFT JOIN gameobject_protos g ON g.Entry = s.Entry
      WHERE s.Type = 2 AND g.Entry IS NULL AND o.Type = 2)                         AS leaked_back_into_live,
    (SELECT COUNT(*) FROM (
        SELECT o.Guid FROM pquest_objectives o
         WHERE o.Type = 2
           AND o.Guid IN (SELECT Objective FROM pquest_spawns_unresolved)
           AND NOT EXISTS (SELECT 1 FROM pquest_spawns s0 WHERE s0.Objective = o.Guid)) z)
                                                                                   AS kill_objectives_empty;
